        ...hits.keyboardUnreachable.length ? ["keyboard-unreachable"] : [],
        ...hits.dialogFocus.length ? ["dialog-focus"] : [],
        ...hits.errorUnassociated.length ? ["error-unassociated"] : [],
        ...hits.liveRegion.length ? ["live-region"] : []
